try{require_csrf((string)($_POST['csrf']??''));$login=valid_login((string)($_POST['login']??''));$c=addon_config();$id=huawei_user_id($c,$login);$check=huawei_exec($c,'display access-user user-id '.$id);$current=huawei_value($check,'User name');if($current===null||strcasecmp($current,$login)!==0)throw new RuntimeException('O UserID mudou e a desconexão foi cancelada.');$out=huawei_exec($c,"system-view\naaa\ncut access-user user-id $id");if(stripos($out,'Error:')!==false||stripos($out,'Unrecognized command')!==false)throw new RuntimeException('O usuário SSH não tem permissão ou o comando foi recusado.');@unlink('/var/cache/mkauth-huawei-online/userid-'.hash('sha256',strtolower($login)));json_response(['ok'=>true,'message'=>"Cliente $login desconectado do Huawei."]);}catch(Throwable $e){json_response(['ok'=>false,'error'=>$e->getMessage()],422);}
